/**
 * `int(str)` with base 10, following CPython's two-step conversion.
 *
 * Results are returned as BigInt because Python integers are unbounded: the
 * graph in this port uses the parsed values as node identities, so collapsing
 * them onto IEEE-754 doubles would merge distinct nodes such as
 * 99999999999999999999998 and 99999999999999999999999.
 */

import { decimalValue, isAsciiSpace, isNonAsciiSpace } from './unicode.mjs';
import { PyValueError } from './errors.mjs';

/**
 * `_PyUnicode_TransformDecimalAndSpaceToASCII`.
 *
 * ASCII code points are passed through untouched, other whitespace collapses to
 * a plain space, other decimal digits become their ASCII counterpart, and
 * anything else becomes '?' so the scanner below rejects it.
 */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint < 127) {
      out += character;
    } else if (isNonAsciiSpace(codePoint)) {
      out += ' ';
    } else {
      const digit = decimalValue(codePoint);
      out += digit < 0 ? '?' : String(digit);
    }
  }
  return out;
}

function invalidLiteral(text) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${JSON.stringify(text)}`,
  );
}

/**
 * `PyLong_FromString` for base 10: optional surrounding whitespace, an optional
 * sign that must be followed immediately by a digit, and digit groups that may
 * be separated by single underscores.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  if (typeof text !== 'string') {
    throw new PyValueError('pyInt() expects a string');
  }

  const scanned = transformDecimalAndSpaceToAscii(text);
  const length = scanned.length;
  let index = 0;

  while (index < length && isAsciiSpace(scanned.charCodeAt(index))) index += 1;

  let negative = false;
  if (index < length && (scanned[index] === '+' || scanned[index] === '-')) {
    negative = scanned[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  while (index < length) {
    const character = scanned[index];
    if (character >= '0' && character <= '9') {
      digits += character;
      previousWasDigit = true;
      index += 1;
    } else if (character === '_' && previousWasDigit) {
      // A single underscore is allowed, but only wedged between two digits;
      // `previousWasDigit` going false here rejects '1__0' and '5_'.
      previousWasDigit = false;
      index += 1;
    } else {
      break;
    }
  }

  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);

  while (index < length && isAsciiSpace(scanned.charCodeAt(index))) index += 1;
  if (index !== length) throw invalidLiteral(text);

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

/**
 * The callable handed to `parser.add_argument(..., type=int)`. `typeName` is
 * what argparse interpolates into its "invalid int value" diagnostic.
 */
export const int = pyInt;
int.typeName = 'int';

