import { PyException } from '../python/errors.mjs';

/** The sentinel that suppresses a default, a dest or a help entry. */
export const SUPPRESS = '==SUPPRESS==';

/**
 * `ArgumentError`: something went wrong while converting or validating one
 * argument. The offending argument's name is prefixed onto the message the same
 * way argparse does it.
 */
export class ArgumentError extends PyException {
  constructor(action, message) {
    const name = ArgumentError.actionName(action);
    super(name === null ? message : `argument ${name}: ${message}`);
    this.action = action;
    this.rawMessage = message;
  }

  /** `argparse._get_action_name`. */
  static actionName(action) {
    if (action === null || action === undefined) return null;
    if (action.optionStrings && action.optionStrings.length > 0) {
      return action.optionStrings.join('/');
    }
    if (action.metavar !== null && action.metavar !== undefined && action.metavar !== SUPPRESS) {
      return action.metavar;
    }
    if (action.dest !== null && action.dest !== undefined && action.dest !== SUPPRESS) {
      return action.dest;
    }
    return null;
  }
}

/**
 * `ArgumentTypeError`: raised by a `type` callable that wants its own message
 * used verbatim rather than the generic "invalid <type> value" wording.
 */
export class ArgumentTypeError extends PyException {}

