/**
 * `argparse.HelpFormatter`: the layout engine behind the usage line and the
 * options list.
 *
 * Every magic number below comes from the original -- the 24-column help
 * position, the `width - 20` clamp on it, the 11-column floor on the help text
 * and the 0.75 threshold that decides whether the program name shares a line
 * with the first option -- because the output has to match column for column.
 */

import { wrap } from '../python/textwrap.mjs';
import { getTerminalColumns } from '../python/terminal.mjs';
import { SUPPRESS } from './errors.mjs';

/**
 * Splits a usage string into the pieces a line break may fall between: a
 * parenthesised group, a bracketed group, or any run of non-space characters.
 */
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** Three or more newlines collapse to a blank line separator. */
const LONG_BREAK = /\n\n\n+/g;

function spaces(count) {
  return ' '.repeat(Math.max(0, count));
}

export class HelpFormatter {
  constructor(prog, { indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    const effectiveWidth = width === null ? getTerminalColumns() - 2 : width;

    this._prog = prog;
    this._indentIncrement = indentIncrement;
    this._maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(effectiveWidth - 20, indentIncrement * 2),
    );
    this._width = effectiveWidth;
    this._currentIndent = 0;
    this._actionMaxLength = 0;
  }

  /**
   * `add_argument` on the formatter: widths are accumulated up front so that
   * every option lines its help text up at the same column.
   */
  registerActions(actions) {
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;
      const invocationLength = this._formatActionInvocation(action).length;
      this._actionMaxLength = Math.max(
        this._actionMaxLength,
        invocationLength + this._indentIncrement,
      );
    }
  }

  /** `_get_default_metavar_for_optional`. */
  _metavarFor(action) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    return String(action.dest).toUpperCase();
  }

  /** `_format_action_invocation`: what appears at the head of a help entry. */
  _formatActionInvocation(action) {
    if (action.optionStrings.length === 0) return this._metavarFor(action);
    if (action.nargs === 0) return action.optionStrings.join(', ');
    const metavar = this._metavarFor(action);
    return action.optionStrings.map((option) => `${option} ${metavar}`).join(', ');
  }

  /** `_format_actions_usage`: the bracketed/bare option list in the usage line. */
  _formatActionsUsage(actions) {
    const parts = [];
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;
      let part;
      if (action.nargs === 0) {
        part = action.formatUsage();
      } else {
        part = `${action.optionStrings[0]} ${this._metavarFor(action)}`;
      }
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts.join(' ');
  }

  /**
   * `_format_usage`. The return value keeps the trailing blank line that the
   * section joiner later collapses.
   */
  formatUsage(actions, prefix = 'usage: ') {
    const prog = this._prog;
    const optionals = actions.filter((action) => action.optionStrings.length > 0);
    const positionals = actions.filter((action) => action.optionStrings.length === 0);
    const actionUsage = this._formatActionsUsage([...optionals, ...positionals]);
    let usage = [prog, actionUsage].filter((piece) => piece !== '').join(' ');

    const textWidth = this._width - this._currentIndent;
    if (prefix.length + usage.length > textWidth) {
      const optionalParts = this._formatActionsUsage(optionals).match(USAGE_PART) ?? [];
      const positionalParts = this._formatActionsUsage(positionals).match(USAGE_PART) ?? [];

      const getLines = (parts, indent, linePrefix = null) => {
        const lines = [];
        let line = [];
        let lineLength = (linePrefix === null ? indent.length : linePrefix.length) - 1;
        for (const part of parts) {
          if (lineLength + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLength = indent.length - 1;
          }
          line.push(part);
          lineLength += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (linePrefix !== null && lines.length > 0) {
          lines[0] = lines[0].slice(indent.length);
        }
        return lines;
      };

      let lines;
      if (prefix.length + prog.length <= 0.75 * textWidth) {
        // Short program name: the first options sit right after it, and
        // continuation lines hang under that column.
        const indent = spaces(prefix.length + prog.length + 1);
        if (optionalParts.length > 0) {
          lines = getLines([prog, ...optionalParts], indent, prefix);
          lines.push(...getLines(positionalParts, indent));
        } else if (positionalParts.length > 0) {
          lines = getLines([prog, ...positionalParts], indent, prefix);
        } else {
          lines = [prog];
        }
      } else {
        // Long program name: it gets a line to itself.
        const indent = spaces(prefix.length);
        let wrapped = getLines([...optionalParts, ...positionalParts], indent);
        if (wrapped.length > 1) {
          wrapped = [...getLines(optionalParts, indent), ...getLines(positionalParts, indent)];
        }
        lines = [prog, ...wrapped];
      }

      usage = lines.join('\n');
    }

    return `${prefix}${usage}\n\n`;
  }

  /** `_format_action`: one entry of the options list, help text included. */
  formatAction(action) {
    const helpPosition = Math.min(this._actionMaxLength + 2, this._maxHelpPosition);
    const helpWidth = Math.max(this._width - helpPosition, 11);
    const actionWidth = helpPosition - this._currentIndent - 2;

    const invocation = this._formatActionInvocation(action);
    let header;
    let indentFirst = 0;
    if (!action.help) {
      header = `${spaces(this._currentIndent)}${invocation}\n`;
    } else if (invocation.length <= actionWidth) {
      header = `${spaces(this._currentIndent)}${invocation.padEnd(actionWidth)}  `;
      indentFirst = 0;
    } else {
      header = `${spaces(this._currentIndent)}${invocation}\n`;
      indentFirst = helpPosition;
    }

    const parts = [header];
    if (action.help && action.help.trim() !== '') {
      const helpLines = wrap(action.help.replace(/\s+/g, ' ').trim(), helpWidth);
      if (helpLines.length > 0) {
        parts.push(`${spaces(indentFirst)}${helpLines[0]}\n`);
        for (const line of helpLines.slice(1)) {
          parts.push(`${spaces(helpPosition)}${line}\n`);
        }
      }
    } else if (!header.endsWith('\n')) {
      parts.push('\n');
    }

    return parts.join('');
  }

  /**
   * A titled block of entries. An empty block contributes nothing, which is why
   * the unused "positional arguments" group never shows up.
   */
  formatSection(heading, actions) {
    const visible = actions.filter((action) => action.help !== SUPPRESS);
    if (visible.length === 0) return '';

    this._currentIndent += this._indentIncrement;
    const items = visible.map((action) => this.formatAction(action)).join('');
    this._currentIndent -= this._indentIncrement;

    return `\n${spaces(this._currentIndent)}${heading}:\n${items}\n`;
  }

  /** `format_help`: collapse runs of blank lines, then normalise the edges. */
  static finish(text) {
    if (text === '') return text;
    const collapsed = text.replace(LONG_BREAK, '\n\n');
    const trimmed = collapsed.replace(/^\n+/, '').replace(/\n+$/, '');
    return trimmed === '' ? '' : `${trimmed}\n`;
  }
}

