   * @param {string|string[]} names one or more option strings, e.g. '--a'
   * @param {object} [options] `action`, `type`, `required`, `default`, `help`,
   *   `metavar` and `dest`, spelled as in Python
   */
  add_argument(names, options = {}) {
    const optionStrings = Array.isArray(names) ? [...names] : [names];
    if (optionStrings.length === 0) {
      throw new PyValueError('add_argument() needs at least one option string');
    }
    for (const optionString of optionStrings) {
      if (!this.prefixChars.includes(optionString[0])) {
        throw new PyValueError(`invalid option string ${pyRepr(optionString)}`);
      }
    }

    const dest = options.dest ?? ArgumentParser._destFor(optionStrings);
    const shared = {
      optionStrings,
      dest,
      type: options.type ?? null,
      choices: options.choices ?? null,
      required: options.required ?? false,
      help: options.help ?? null,
      metavar: options.metavar ?? null,
      defaultValue: 'default' in options ? options.default : null,
    };

    let action;
    switch (options.action ?? 'store') {
      case 'store':
        action = new StoreAction(shared);
        break;
      case 'help':
        action = new HelpAction({ ...shared, required: false });
        break;
      default:
        throw new PyValueError(`unknown action ${pyRepr(options.action)}`);
    }

    this._actions.push(action);
    for (const optionString of optionStrings) {
      this._optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this._hasNegativeNumberOptionals = true;
    }
    return action;
  }

  /** A long option wins when deriving the destination name, as in argparse. */
  static _destFor(optionStrings) {
    let chosen = optionStrings[0];
    for (const optionString of optionStrings) {
      if (optionString.startsWith('--')) {
        chosen = optionString;
        break;
      }
    }
    return chosen.replace(/^-+/, '').replace(/-/g, '_');
  }

  // -- formatting ------------------------------------------------------------

  _formatter() {
    const formatter = new HelpFormatter(this.prog);
    formatter.registerActions(this._actions);
    return formatter;
  }

  format_usage() {
    const formatter = this._formatter();
    return HelpFormatter.finish(formatter.formatUsage(this._actions));
  }

  format_help() {
    const formatter = this._formatter();
    const positionals = this._actions.filter((action) => action.optionStrings.length === 0);
    const optionals = this._actions.filter((action) => action.optionStrings.length > 0);
    const text =
      formatter.formatUsage(this._actions) +
      formatter.formatSection('positional arguments', positionals) +
      formatter.formatSection('options', optionals);
    return HelpFormatter.finish(text);
  }

  print_usage(write = writeStdout) {
    write(this.format_usage());
  }

  print_help(write = writeStdout) {
    write(this.format_help());
  }

  /** `exit`: emit an optional message and unwind with a status code. */
  exit(status = 0, message = null) {
    if (message) writeStderr(message);
    throw new SystemExit(status);
  }

  /** `error`: usage line, then `prog: error: message`, then status 2. */
  error(message) {
    this.print_usage(writeStderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  // -- parsing ---------------------------------------------------------------

  /**
   * `parse_args`: like {@link parse_known_args} but leftover arguments are an
   * error rather than a second return value.
   *
   * @param {string[]} [argv] defaults to the process command line
   */
  parse_args(argv = getArgv()) {
    const [namespace, extras] = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * `parse_known_args`.
   *
   * @param {string[]} [argv]
   * @returns {[Record<string, unknown>, string[]]}
   */
  parse_known_args(argv = getArgv()) {
    const namespace = {};
    for (const action of this._actions) {
      if (action.dest === SUPPRESS) continue;
      if (action.defaultValue === SUPPRESS) continue;
      namespace[action.dest] = action.defaultValue;
    }

    try {
      return this._parseKnownArgs([...argv], namespace);
    } catch (error) {
      if (error instanceof ArgumentError) {
        this.error(error.message);
      }
      throw error;
    }
  }

  /**
   * Classify one token: `null` for something that is not an option, otherwise
   * `[action, optionString, explicitArg]` with a null action standing for an
   * option string the parser does not know. Mirrors `_parse_optional`.
   */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this._optionStringActions.has(argString)) {
      return [this._optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      if (this._optionStringActions.has(optionString)) {
        return [
          this._optionStringActions.get(optionString),
          optionString,
          argString.slice(equals + 1),
        ];
      }
    }

    const candidates = this._optionTuples(argString);
    if (candidates.length > 1) {
      const matches = candidates.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (candidates.length === 1) {
      return candidates[0];
    }

    // Something like -5 is a value, not an unknown option, unless the parser
    // actually declares an option that looks like a negative number.
    if (NEGATIVE_NUMBER.test(argString) && !this._hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  /** `_get_option_tuples`: abbreviation and joined-short-option candidates. */
  _optionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;

    if (chars.includes(argString[0]) && chars.includes(argString[1])) {
      if (!this.allowAbbrev) return result;
      const equals = argString.indexOf('=');
      const prefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString.startsWith(prefix)) result.push([action, optionString, explicitArg]);
      }
      return result;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this._optionStringActions) {
      if (optionString === shortPrefix) {
        result.push([action, optionString, shortExplicitArg]);
      } else if (optionString.startsWith(argString)) {
        result.push([action, optionString, null]);
      }
    }
    return result;
  }

  /**
   * `_get_nargs_pattern`, restricted to optionals. The `-` placeholders that
   * stand for a `--` separator are stripped, which is why `--e -- 5` reports a
   * missing argument instead of consuming across the separator.
   */
  _nargsPattern(action) {
    const nargs = action.nargs;
    const body = nargs === null ? '(-*A-*)' : `(-*${'A'.repeat(nargs)}-*)`;
    return body.replaceAll('-*', '').replaceAll('-', '');
  }

  /** `_match_argument`: how many following tokens this action swallows. */
  _matchArgument(action, pattern) {
    const match = new RegExp(`^${this._nargsPattern(action)}`).exec(pattern);
    if (match === null) {
      const message =
        action.nargs === null
          ? 'expected one argument'
          : action.nargs === 1
            ? 'expected one argument'
            : `expected ${action.nargs} arguments`;
      throw new ArgumentError(action, message);
    }
    return match[1].length;
  }

  /** `_get_value`: run the `type` callable and translate its failures. */
  _getValue(action, argString) {
    const typeFunction = action.type;
    if (typeFunction === null) return argString;

    try {
      return typeFunction(argString);
    } catch (error) {
      if (error instanceof ArgumentTypeError) {
        throw new ArgumentError(action, error.message);
      }
      if (error instanceof PyValueError || error instanceof PyTypeError) {
        const typeName = typeFunction.typeName ?? typeFunction.name ?? 'value';
        throw new ArgumentError(
          action,
          `invalid ${typeName} value: ${pyRepr(argString)}`,
        );
      }
      throw error;
    }
  }

  /** `_check_value`: enforce `choices`. */
  _checkValue(action, value) {
    if (action.choices !== null && !action.choices.includes(value)) {
      const choices = action.choices.map((choice) => pyRepr(choice)).join(', ');
      throw new ArgumentError(
        action,
        `invalid choice: ${pyRepr(value)} (choose from ${choices})`,
      );
    }
  }

  /** `_get_values`. */
  _getValues(action, argStrings) {
    if (argStrings.length === 1 && action.nargs === null) {
      const value = this._getValue(action, argStrings[0]);
      this._checkValue(action, value);
      return value;
    }
    const values = argStrings.map((argString) => this._getValue(action, argString));
    for (const value of values) this._checkValue(action, value);
    return values;
  }

  /** `_parse_known_args`. */
  _parseKnownArgs(argStrings, namespace) {
    // Classify every token first. A '--' separator is marked '-' and forces
    // everything after it to count as a plain value.
    const optionTuples = new Map();
    const patternChars = [];
    for (let index = 0; index < argStrings.length; index += 1) {
      if (argStrings[index] === '--') {
        patternChars.push('-');
        for (index += 1; index < argStrings.length; index += 1) patternChars.push('A');
        break;
      }
      const parsed = this._parseOptional(argStrings[index]);
      if (parsed === null) {
        patternChars.push('A');
      } else {
        optionTuples.set(index, parsed);
        patternChars.push('O');
      }
    }
    const pattern = patternChars.join('');

    const extras = [];
    const seenActions = new Set();

    const takeAction = (action, argumentStrings, optionString) => {
      seenActions.add(action);
      const values = this._getValues(action, argumentStrings);
      action.call(this, namespace, values, optionString);
    };

    const consumeOptional = (startIndex) => {
      let [action, optionString, explicitArg] = optionTuples.get(startIndex);
      const actionTuples = [];
      let stop = startIndex;

      for (;;) {
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this._matchArgument(action, 'A');
          if (
            argCount === 0 &&
            !this.prefixChars.includes(optionString[1]) &&
            explicitArg !== ''
          ) {
            // A joined run of single-dash flags such as -hx: peel off the first
            // one and reconsider the remainder as another option string.
            actionTuples.push([action, [], optionString]);
            const nextOptionString = optionString[0] + explicitArg[0];
            const nextExplicitArg = explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
            if (this._optionStringActions.has(nextOptionString)) {
              action = this._optionStringActions.get(nextOptionString);
              optionString = nextOptionString;
              explicitArg = nextExplicitArg;
              stop = startIndex + 1;
              continue;
            }
            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
          }
          if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          }
          throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
        }

        const start = startIndex + 1;
        const argCount = this._matchArgument(action, pattern.slice(start));
        stop = start + argCount;
        actionTuples.push([action, argStrings.slice(start, stop), optionString]);
        break;
      }

      for (const [tupleAction, tupleArgs, tupleOptionString] of actionTuples) {
        takeAction(tupleAction, tupleArgs, tupleOptionString);
      }
      return stop;
    };

    const optionIndices = [...optionTuples.keys()].sort((left, right) => left - right);
    const maxOptionIndex = optionIndices.length > 0 ? optionIndices[optionIndices.length - 1] : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((index) => index >= startIndex);
      // With no positionals declared, nothing can consume the tokens sitting
      // between here and the next option, so they are leftovers.
      if (startIndex !== nextOptionIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(nextOptionIndex);
    }
    extras.push(...argStrings.slice(startIndex));

    const missing = [];
    for (const action of this._actions) {
      if (!seenActions.has(action) && action.required) {
        missing.push(ArgumentError.actionName(action));
      }
    }
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }
}

