/**
 * Node identity.
 *
 * Python graphs key their nodes by hash and equality, so `1`, `1.0` and `True`
 * are one and the same node while arbitrarily large integers stay distinct.
 * JavaScript has no single value type with those properties, so every node is
 * reduced to a canonical string: numeric values collapse across the Number and
 * BigInt divide, and everything else is tagged by type so that, say, the string
 * '1' can never be mistaken for the integer 1.
 */

/**
 * @param {unknown} value
 * @returns {string} a key equal for exactly those values Python considers the
 *   same dictionary key
 */
export function nodeKey(value) {
  switch (typeof value) {
    case 'bigint':
      return `i${value.toString()}`;
    case 'boolean':
      return value ? 'i1' : 'i0';
    case 'number':
      if (Number.isNaN(value)) return 'f:nan';
      if (!Number.isFinite(value)) return value > 0 ? 'f:inf' : 'f:-inf';
      // An integral double is the same node as the corresponding integer, which
      // is what makes G.add_edge(1, 2) and G.add_edge(1.0, 2) coincide.
      if (Number.isInteger(value)) return `i${BigInt(value).toString()}`;
      return `f${value}`;
    case 'string':
      return `s${value}`;
    case 'undefined':
      return 'None';
    case 'object': {
      if (value === null) return 'None';
      if (Array.isArray(value)) {
        // Length-prefixed so that nested keys cannot run together.
        const parts = value.map((item) => {
          const encoded = nodeKey(item);
          return `${encoded.length}:${encoded}`;
        });
        return `t${value.length}[${parts.join('')}]`;
      }
      return `o${objectIdentity(value)}`;
    }
    default:
      return `o${objectIdentity(value)}`;
  }
}

let nextIdentity = 1;
const identities = new WeakMap();

/** Objects without value semantics fall back to identity, as in CPython. */
function objectIdentity(value) {
  let identity = identities.get(value);
  if (identity === undefined) {
    identity = nextIdentity;
    nextIdentity += 1;
    identities.set(value, identity);
  }
  return identity;
}

