  has_edge(source, target) {
    const neighbours = this._adj.get(this.key(source));
    return neighbours !== undefined && neighbours.has(this.key(target));
  }

  /** Node values, in insertion order. */
  nodes() {
    return [...this._nodeValue.values()];
  }

  number_of_nodes() {
    return this._node.size;
  }

  /** `[source, target]` pairs, each undirected edge reported once. */
  edges() {
    const seen = new Set();
    const result = [];
    for (const [sourceKey, neighbours] of this._adj) {
      for (const targetKey of neighbours.keys()) {
        const canonical = sourceKey <= targetKey ? `${sourceKey}�${targetKey}` : `${targetKey}�${sourceKey}`;
        if (seen.has(canonical)) continue;
        seen.add(canonical);
        result.push([this._nodeValue.get(sourceKey), this._nodeValue.get(targetKey)]);
      }
    }
    return result;
  }

  number_of_edges() {
    return this.edges().length;
  }

  _adjacencyOf(value) {
    const neighbours = this._adj.get(this.key(value));
    if (neighbours === undefined) {
      throw new NetworkXError(`The node ${String(value)} is not in the graph.`);
    }
    return neighbours;
  }

  /** Neighbour values of a node. */
  neighbors(value) {
    return [...this._adjacencyOf(value).keys()].map((key) => this._nodeValue.get(key));
  }

  degree(value) {
    const neighbours = this._adjacencyOf(value);
    // A self-loop contributes two to an undirected degree.
    return neighbours.size + (neighbours.has(this.key(value)) ? 1 : 0);
  }
}

