 * `networkx.DiGraph`: a directed simple graph.
 *
 * Successors and predecessors are stored separately so that in- and out-degrees
 * are both O(1), which is what Kahn's algorithm in `algorithms/dag.mjs` wants.
 */

import { Graph } from './graph.mjs';

export class DiGraph extends Graph {
  constructor() {
    super();
    /** Successors; aliased as `_adj` so inherited lookups follow edge direction. */
    this._succ = this._adj;
    /** @type {Map<string, Map<string, object>>} */
    this._pred = new Map();
  }

  is_directed() {
    return true;
  }

  add_node(value, attributes = {}) {
    const key = this.key(value);
    const isNew = !this._node.has(key);
    super.add_node(value, attributes);
    if (isNew) this._pred.set(key, new Map());
  }

  add_edge(source, target, attributes = {}) {
    this.add_node(source);
    this.add_node(target);
    const sourceKey = this.key(source);
    const targetKey = this.key(target);

    const existing = this._succ.get(sourceKey).get(targetKey) ?? {};
    Object.assign(existing, attributes);
    this._succ.get(sourceKey).set(targetKey, existing);
    this._pred.get(targetKey).set(sourceKey, existing);
  }

  has_edge(source, target) {
    const successors = this._succ.get(this.key(source));
    return successors !== undefined && successors.has(this.key(target));
  }

  /** Directed edges as `[source, target]` pairs, in insertion order. */
  edges() {
    const result = [];
    for (const [sourceKey, successors] of this._succ) {
      for (const targetKey of successors.keys()) {
        result.push([this._nodeValue.get(sourceKey), this._nodeValue.get(targetKey)]);
      }
    }
    return result;
  }

  successors(value) {
    return this.neighbors(value);
  }

  predecessors(value) {
    return [...this._predecessorsOf(value).keys()].map((key) => this._nodeValue.get(key));
  }

  _predecessorsOf(value) {
    const predecessors = this._pred.get(this.key(value));
    if (predecessors === undefined) {
      throw new Error(`The node ${String(value)} is not in the digraph.`);
    }
    return predecessors;
  }

  /** `[node, in-degree]` pairs for every node, in insertion order. */
  in_degree() {
    return [...this._nodeValue.entries()].map(([key, value]) => [value, this._pred.get(key).size]);
  }

  /** `[node, out-degree]` pairs for every node, in insertion order. */
  out_degree() {
    return [...this._nodeValue.entries()].map(([key, value]) => [value, this._succ.get(key).size]);
  }

  degree(value) {
    return this._adjacencyOf(value).size + this._predecessorsOf(value).size;
