/**
 * Directed acyclic graph algorithms.
 *
 * The acyclicity test is the one NetworkX uses: attempt a topological ordering
 * with Kahn's algorithm and see whether every node comes out. Anything left over
 * still has an unsatisfied predecessor, which can only happen inside a cycle --
 * and a self-loop counts, since a node is then its own unsatisfied predecessor.
 */

import { NetworkXError, NetworkXUnfeasible } from '../exceptions.mjs';

/**
 * Nodes grouped into layers: every node in a generation depends only on nodes in
 * earlier ones.
 *
 * @param {import('../classes/digraph.mjs').DiGraph} G
 * @yields {unknown[]} one generation of node values
 */
export function* topological_generations(G) {
  if (!G.is_directed()) {
    throw new NetworkXError('Topological sort not defined on undirected graphs.');
  }

  const remainingInDegree = new Map();
  let zeroInDegree = [];
  for (const [node, degree] of G.in_degree()) {
    if (degree > 0) remainingInDegree.set(G.key(node), degree);
    else zeroInDegree.push(node);
  }

  while (zeroInDegree.length > 0) {
    const generation = zeroInDegree;
    zeroInDegree = [];
    for (const node of generation) {
      for (const child of G.neighbors(node)) {
        const childKey = G.key(child);
        const remaining = remainingInDegree.get(childKey) - 1;
        remainingInDegree.set(childKey, remaining);
        if (remaining === 0) {
          zeroInDegree.push(child);
          remainingInDegree.delete(childKey);
        }
      }
    }
    yield generation;
  }

  if (remainingInDegree.size > 0) {
    throw new NetworkXUnfeasible(
      'Graph contains a cycle or graph changed during iteration',
    );
  }
}

/**
 * A topological ordering of the nodes.
 *
 * @param {import('../classes/digraph.mjs').DiGraph} G
 * @yields {unknown} node values, dependencies first
 */
export function* topological_sort(G) {
  for (const generation of topological_generations(G)) {
    yield* generation;
  }
}

/**
 * Whether `G` is a directed acyclic graph. Undirected graphs are never one, and
 * a graph with no nodes vacuously is.
 *
 * @param {import('../classes/graph.mjs').Graph} G
 * @returns {boolean}
 */
export function is_directed_acyclic_graph(G) {
  if (!G.is_directed()) return false;
  try {
    // eslint-disable-next-line no-unused-vars
    for (const node of topological_sort(G)) {
      // Drained purely for its side effect of completing the ordering.
    }
    return true;
  } catch (error) {
    if (error instanceof NetworkXUnfeasible) return false;
    throw error;
  }
}

