// Independent oracle check: brute-force cycle detection over every 5-tuple from
// a small alphabet, compared against the ported library in-process.
import { DiGraph, is_directed_acyclic_graph } from '/output/lib/networkx/index.mjs';

// Deliberately unrelated implementation: build an adjacency set keyed by the raw
// numbers and look for a cycle with a colouring DFS.
function oracleIsDag(a, b, c, d, e) {
  const edges = [[a, b], [b, c], [c, d], [d, e]];
  const adjacency = new Map();
  for (const [u, v] of edges) {
    if (!adjacency.has(u)) adjacency.set(u, new Set());
    if (!adjacency.has(v)) adjacency.set(v, new Set());
    adjacency.get(u).add(v);
  }
  const colour = new Map();
  const visit = (node) => {
    colour.set(node, 1);
    for (const next of adjacency.get(node)) {
      const state = colour.get(next) ?? 0;
      if (state === 1) return false;
      if (state === 0 && !visit(next)) return false;
    }
    colour.set(node, 2);
    return true;
  };
  for (const node of adjacency.keys()) {
    if ((colour.get(node) ?? 0) === 0 && !visit(node)) return false;
  }
  return true;
}

let checked = 0;
let mismatches = 0;
const alphabet = [0, 1, 2, 3];
for (const a of alphabet) {
  for (const b of alphabet) {
    for (const c of alphabet) {
      for (const d of alphabet) {
        for (const e of alphabet) {
          const G = new DiGraph();
          G.add_edges_from([[BigInt(a), BigInt(b)], [BigInt(b), BigInt(c)], [BigInt(c), BigInt(d)], [BigInt(d), BigInt(e)]]);
          const got = is_directed_acyclic_graph(G);
          const want = oracleIsDag(a, b, c, d, e);
          checked += 1;
          if (got !== want) {
            mismatches += 1;
            console.log('MISMATCH', [a, b, c, d, e], 'port', got, 'oracle', want);
          }
        }
      }
    }
  }
}
console.log(`${checked - mismatches}/${checked} agree with the independent oracle`);

// Node identity must survive values beyond 2**53.
const huge = new DiGraph();
const big1 = 99999999999999999999998n;
const big2 = 99999999999999999999999n;
huge.add_edges_from([[big1, big2], [big2, 7n], [7n, 8n], [8n, 9n]]);
console.log('distinct huge integers stay distinct:', is_directed_acyclic_graph(huge) === true);
const collapsed = new DiGraph();
collapsed.add_edges_from([[big1, big2], [big2, big1], [7n, 8n], [8n, 9n]]);
console.log('huge integer cycle detected:', is_directed_acyclic_graph(collapsed) === false);

// Python dict-key equivalence across numeric spellings.
const unified = new DiGraph();
unified.add_edge(1, 2);
console.log('1 and 1n are one node:', unified.has_node(1n) && unified.has_node(true) && unified.number_of_nodes() === 2);
console.log("integer 1 is not the string '1':", !unified.has_node('1'));

